cd /tmp; python3 - <<'EOF'
import pycdlib,io
iso=pycdlib.PyCdlib(); iso.open('/app/alpine.iso')
for src,dst in [('/BOOT/VMLINUZ_LTS.;1','/tmp/vmlinuz-lts'),('/BOOT/INITRAMFS_LTS.;1','/tmp/initramfs-lts')]:
    with open(dst,'wb') as f: iso.get_file_from_iso_fp(f, iso_path=src)
    import os; print(dst, os.path.getsize(dst))
# check openssh apk present
found=[]
for d in iso.walk(iso_path='/APKS'):
    for f in d[2]:
        if 'OPENSSH' in f: found.append(f)
print('OPENSSH apks:', found)
iso.close()
EOF

